package fizeau

import (
	"context"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/serverinstance"
)

// RouteStatus returns live routing state for configured providers/models.
// It is the operator dashboard view: cooldowns, recent decisions, and
// per-candidate health. Distinct from per-request ResolveRoute.
func (s *service) RouteStatus(ctx context.Context) (*RouteStatusReport, error) {
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	sc := s.opts.ServiceConfig
	report := &RouteStatusReport{
		GeneratedAt: time.Now(),
	}
	// ADR-006 §5: populate routing-quality over a recent window
	// (RouteStatusRoutingQualityWindow) regardless of whether a route
	// catalog is configured — the metric reflects Execute traffic, not
	// configured routes.
	if s != nil && s.routingQuality != nil {
		recent := s.routingQuality.snapshotRecent(RouteStatusRoutingQualityWindow, time.Time{})
		report.RoutingQuality = computeRoutingQualityMetricsFromRecords(recent)
	}
	if sc == nil {
		return report, nil
	}

	cooldown := s.routeAttemptTTL()
	activeAttempts := s.activeRouteAttempts(report.GeneratedAt, cooldown)

	entries := make(map[string]*RouteStatusEntry)
	order := make([]string, 0)
	for i, providerName := range sc.ProviderNames() {
		provider, ok := sc.Provider(providerName)
		if !ok {
			continue
		}
		model := provider.Model
		if model == "" {
			model = providerName
		}
		entry, ok := entries[model]
		if !ok {
			entry = &RouteStatusEntry{Model: model, Strategy: "auto"}
			if cached, ok := s.lookupRouteDecision(model); ok {
				entry.LastDecision = cached.decision
				entry.LastDecisionAt = cached.at
				entry.SelectedEndpoint = cached.decision.Endpoint
				entry.SelectedServerInstance = cached.decision.ServerInstance
				entry.Sticky = cached.decision.Sticky
			}
			entries[model] = entry
			order = append(order, model)
		}
		cs := RouteCandidateStatus{
			Provider:       providerName,
			Model:          model,
			ServerInstance: serverinstance.Normalize(provider.BaseURL, provider.ServerInstance),
			Priority:       len(sc.ProviderNames()) - i,
		}
		if attemptCooldown := routeAttemptCandidateCooldown(activeAttempts, providerName, model, cooldown); attemptCooldown != nil {
			cs.Cooldown = attemptCooldown
		}
		cs.Healthy = cs.Cooldown == nil
		entry.Candidates = append(entry.Candidates, cs)
	}

	report.Routes = make([]RouteStatusEntry, 0, len(order))
	for _, model := range order {
		report.Routes = append(report.Routes, *entries[model])
	}

	return report, nil
}

func routeAttemptCandidateCooldown(records []routehealth.Record, providerName, model string, cooldown time.Duration) *CooldownState {
	var newest *routehealth.Record
	for i := range records {
		record := &records[i]
		if record.Key.Provider == "" {
			continue
		}
		if providerName != "" && record.Key.Provider != providerName {
			continue
		}
		if record.Key.Model != "" && model != "" && record.Key.Model != model {
			continue
		}
		if newest == nil || record.RecordedAt.After(newest.RecordedAt) {
			newest = record
		}
	}
	if newest == nil {
		return nil
	}
	return routeAttemptCooldown(*newest, cooldown)
}

// cacheRouteDecision stores a ResolveRoute result keyed by routeKey.
// Called by ResolveRoute after a successful resolution.
func (s *service) cacheRouteDecision(routeKey string, dec *RouteDecision) {
	if routeKey == "" || dec == nil {
		return
	}
	s.lastDecisionMu.Lock()
	defer s.lastDecisionMu.Unlock()
	if s.lastDecisionCache == nil {
		s.lastDecisionCache = make(map[string]lastDecisionEntry)
	}
	s.lastDecisionCache[routeKey] = lastDecisionEntry{
		decision: dec,
		at:       time.Now(),
	}
}

// lookupRouteDecision retrieves a cached decision for routeKey.
func (s *service) lookupRouteDecision(routeKey string) (lastDecisionEntry, bool) {
	s.lastDecisionMu.RLock()
	defer s.lastDecisionMu.RUnlock()
	if s.lastDecisionCache == nil {
		return lastDecisionEntry{}, false
	}
	e, ok := s.lastDecisionCache[routeKey]
	return e, ok
}

// Package registry is the single source of truth for provider-type →
// factory mappings.
//
// Why this package exists. Before it, the agent had two parallel
// factories that knew about provider types: internal/config/config.go
// `BuildProvider` (config-time) and service_native_provider.go
// `buildNativeProvider` (service-execute time). When lucebox + vllm
// were added in v0.9.18-.20, only the first factory got the new types;
// the second one rejected requests pinning those providers at execute
// time. Two factories drifting is the architectural smell `agent-8e4eb44c`
// was filed to fix.
//
// Each provider package registers a Descriptor in its init(). Both
// factories call Lookup. New providers are one Register call away from
// being usable through every code path.
//
// The registry deliberately covers only the factory drift case in v1.
// Other type-switch sites (default port, base URL, surface map,
// capability flags, validators) are local to internal/config and
// don't have the cross-package drift problem; they stay there. Future
// drift cases can be additively folded into the registry as they appear.
package registry

import (
	"sort"
	"sync"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/quotaheaders"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

// Inputs is the canonical factory input shape. Both the config-time
// path (internal/config builds this from a ProviderConfig) and the
// service-time path (service_native_provider builds this from a
// ServiceProviderEntry) populate it. Provider factories take exactly
// one argument so the call sites can't accidentally diverge.
type Inputs struct {
	// ProviderName is the user-facing config name for this provider
	// (e.g., "vidar-omlx"). Distinct from the provider TYPE (e.g.,
	// "omlx"). Some factories include it in attribution metadata.
	ProviderName string

	// BaseURL is the resolved endpoint (with default substituted).
	BaseURL string
	// APIKey is the bearer token; empty for unauthenticated endpoints.
	APIKey string
	// Model is the configured default; empty when discovery is in use.
	Model string

	// ModelPattern is an optional regex used by openai-compat providers
	// during model discovery (Tier-2 ranking).
	ModelPattern string

	// KnownModels maps surface model IDs to canonical IDs from the
	// model catalog. Used by openai-compat providers to recognize
	// catalog-tracked models on a discovery list.
	KnownModels map[string]string

	// Headers is extra HTTP headers (OpenRouter, Azure, custom).
	Headers map[string]string

	// Reasoning is the per-provider default reasoning policy.
	Reasoning reasoning.Reasoning

	// ModelReasoningWire is a model_id → reasoning_wire map sourced
	// from the catalog. Today only openrouter and openai-compat
	// providers consume it; others ignore it.
	ModelReasoningWire map[string]string

	// QuotaSignalObserver, when set, is forwarded to provider factories
	// that support per-response rate-limit-header parsing (anthropic,
	// openai, openrouter). The service layer wires this to the provider
	// quota state machine so dispatch can route around providers whose
	// subscription/daily cap is hit. Providers that do not parse rate-limit
	// headers ignore this field.
	QuotaSignalObserver func(quotaheaders.Signal)
}

// Factory builds a provider from canonical inputs.
type Factory func(Inputs) agentcore.Provider

// Descriptor pairs a provider type with its factory + a small set of
// invariants. Provider packages register these in init().
type Descriptor struct {
	// Type is the canonical provider-type string (e.g., "omlx").
	// Matches the `type:` value in user config and the descriptor's
	// case in internal/config switches.
	Type string

	// Factory builds an agent.Provider from canonical inputs.
	Factory Factory

	// DefaultBaseURL is used by the config-normalizer when no base_url
	// is explicitly set.
	DefaultBaseURL string

	// DefaultPort is used by endpoint-config inference when only a
	// host is supplied. 0 means "no inference; require explicit BaseURL".
	DefaultPort int
}

var (
	mu      sync.RWMutex
	entries = map[string]Descriptor{}
)

// Register installs a provider Descriptor. Called from each provider
// package's init() function. Re-registering the same type panics —
// duplicate registration is always a programmer error.
func Register(d Descriptor) {
	if d.Type == "" {
		panic("provider/registry: Descriptor.Type is required")
	}
	if d.Factory == nil {
		panic("provider/registry: Descriptor.Factory is required for type " + d.Type)
	}
	mu.Lock()
	defer mu.Unlock()
	if _, exists := entries[d.Type]; exists {
		panic("provider/registry: duplicate registration for type " + d.Type)
	}
	entries[d.Type] = d
}

// Lookup returns the Descriptor for a provider type, or false if the
// type is not registered.
func Lookup(typ string) (Descriptor, bool) {
	mu.RLock()
	defer mu.RUnlock()
	d, ok := entries[typ]
	return d, ok
}

// Types returns all registered provider type names in sorted order.
// Used by validators and conformance descriptors that iterate over
// every known provider type.
func Types() []string {
	mu.RLock()
	defer mu.RUnlock()
	out := make([]string, 0, len(entries))
	for t := range entries {
		out = append(out, t)
	}
	sort.Strings(out)
	return out
}

package serverinstance

import (
	"net"
	"net/url"
	"strings"
)

// Normalize returns the explicit server instance when present, otherwise a
// deterministic identity derived from baseURL's host and port.
//
// The derived identity ignores URL path components so provider endpoints that
// differ only by `/v1` root normalization still collapse to the same
// server-instance label.
func Normalize(baseURL, explicit string) string {
	if trimmed := strings.TrimSpace(explicit); trimmed != "" {
		return trimmed
	}
	return FromBaseURL(baseURL)
}

// FromBaseURL derives a stable server-instance label from the URL host/port.
func FromBaseURL(baseURL string) string {
	trimmed := strings.TrimSpace(baseURL)
	if trimmed == "" {
		return ""
	}
	parsed, err := url.Parse(trimmed)
	if err != nil {
		return fallbackHostPort(trimmed)
	}
	host := strings.TrimSpace(parsed.Hostname())
	if host == "" {
		return fallbackHostPort(trimmed)
	}
	port := strings.TrimSpace(parsed.Port())
	if port == "" {
		return host
	}
	return host + ":" + port
}

func fallbackHostPort(raw string) string {
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return ""
	}
	host, port, err := net.SplitHostPort(raw)
	if err == nil && host != "" {
		if port != "" {
			return host + ":" + port
		}
		return host
	}
	raw = strings.TrimPrefix(raw, "http://")
	raw = strings.TrimPrefix(raw, "https://")
	raw = strings.TrimSuffix(raw, "/v1")
	raw = strings.TrimSuffix(raw, "/")
	return raw
}

